package game

import "fmt"

type Cell struct {
	Point Point
	Tile  Tile
}

// View owns copies of everything it exposes; it contains no enemy inventories.
// Legal actions are generated by the same checks used by Apply, not AI rules.
type View struct {
	Calendar Calendar
	Self     Tribe
	Cells    []Cell
	Legal    []Action
	Armies   []ArmyInfo // Currently visible forces, without enemy military orders.
}

func (s *State) View(id int) (View, error) {
	if id < 0 || id >= TribeCount {
		return View{}, fmt.Errorf("部落编号无效")
	}
	v := View{Calendar: s.Calendar, Self: s.Tribes[id]}
	v.Armies = s.visibleArmies(id)
	for y, row := range s.Tiles {
		for x, tile := range row {
			p := Point{x, y}
			if v.Self.Explored[y][x] {
				v.Cells = append(v.Cells, Cell{p, tile})
				v.addLegal(s, id, Action{Claim, p})
				v.addLegal(s, id, Action{BuildFarm, p})
			} else if s.adjacentTo(id, p) {
				v.addLegal(s, id, Action{Explore, p})
			}
		}
	}
	v.addLegal(s, id, Action{Kind: Train})
	return v, nil
}

func (v *View) addLegal(s *State, id int, a Action) {
	if s.checkAction(id, a) == nil {
		v.Legal = append(v.Legal, a)
	}
}
